package com.minewaku.chatter.identityaccess.user.internal.application;
import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.minewaku.chatter.identityaccess.user.*; import com.minewaku.chatter.identityaccess.user.internal.model.*; import com.minewaku.chatter.identityaccess.user.internal.port.*;
@Service public class ManageUserAccountService implements EnableUserAccountUseCase,DisableUserAccountUseCase,LockUserAccountUseCase,UnlockUserAccountUseCase,SoftDeleteUserAccountUseCase,ActivateAfterVerificationUseCase { private final UserAccountRepository repo; public ManageUserAccountService(UserAccountRepository r){repo=r;} private UserAccount get(long id){return repo.findById(new UserId(id)).orElseThrow(()->new IllegalArgumentException("User account not found"));} private boolean save(UserAccount a,boolean changed){if(changed)repo.save(a);return changed;} @Transactional public EnableUserAccountUseCase.Result handle(EnableUserAccountUseCase.Command c){UserAccount a=get(c.userId());return new EnableUserAccountUseCase.Result(save(a,a.enable()));} @Transactional public DisableUserAccountUseCase.Result handle(DisableUserAccountUseCase.Command c){UserAccount a=get(c.userId());return new DisableUserAccountUseCase.Result(save(a,a.disable()));} @Transactional public LockUserAccountUseCase.Result handle(LockUserAccountUseCase.Command c){UserAccount a=get(c.userId());return new LockUserAccountUseCase.Result(save(a,a.lock()));} @Transactional public UnlockUserAccountUseCase.Result handle(UnlockUserAccountUseCase.Command c){UserAccount a=get(c.userId());return new UnlockUserAccountUseCase.Result(save(a,a.unlock()));} @Transactional public SoftDeleteUserAccountUseCase.Result handle(SoftDeleteUserAccountUseCase.Command c){UserAccount a=get(c.userId());return new SoftDeleteUserAccountUseCase.Result(save(a,a.softDelete()));} @Transactional public ActivateAfterVerificationUseCase.Result handle(ActivateAfterVerificationUseCase.Command c){UserAccount a=get(c.userId());return new ActivateAfterVerificationUseCase.Result(save(a,a.activateAfterVerification()));} }